import { Model } from '../../js/model.js';
import { View } from '../../js/view.js';
import { TerminalCommands } from './Commands.js';
import { TerminalFS } from './Filesystem.js';
import { TerminalEffects } from './Effects.js';

export const TerminalApp = {
  history: [],
  historyIndex: 0,
  draft: "",
  isOpen: false,
  welcomed: false,
  els: {},
